// 자바 11+ 는 charset 을 받는 생성자가 있다
try (PrintWriter w = new PrintWriter("a.txt", StandardCharsets.UTF_8)) {
    w.println("a");
    w.println("b");
    w.printf("%s = %d%n", "count", 3);    // 형식 출력도 된다
}

// 결과는 4바이트 — 61 0a 62 0a
// println 이 줄바꿈을 붙이고, 그 줄바꿈은 System.lineSeparator() 다(4.5절)

